"""SQLAlchemy models for the `ontology` schema.

    Metamodel (definitions)   object_type, property_type, link_type, action_type
    Runtime   (instances)     object_instance, link_instance, action_execution, writeback_outbox
    Governance                audit_log (append-only, hash-chained per tenant)

Conventions
    * Every row carries tenant_id; Postgres row-level security enforces isolation.
    * Primary keys are time-ordered UUIDv7 generated by PostgreSQL 18 (`uuidv7()`).
    * Enumerations are VARCHAR + CHECK rather than native enums, so adding a value is an
      ordinary migration instead of an ALTER TYPE.
    * api_name is the stable machine identifier: PascalCase for object types, camelCase
      for properties, links and actions. display_name is free text.

The schema itself is owned by Alembic (migrations/versions). tests/test_migration_drift.py
fails if these models and the migrated database disagree.
"""

from __future__ import annotations

import enum
import uuid
from datetime import datetime
from typing import Any

from geoalchemy2 import Geometry
from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    DateTime,
    Enum,
    FetchedValue,
    ForeignKey,
    Index,
    Integer,
    LargeBinary,
    MetaData,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, JSONB, UUID
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship

# --------------------------------------------------------------------------- #
# Enumerations
# --------------------------------------------------------------------------- #


class LifecycleStatus(enum.StrEnum):
    DRAFT = "draft"  # editable, invisible to operators
    ACTIVE = "active"  # in use; breaking changes are refused
    DEPRECATED = "deprecated"  # readable, no new writes or executions


class PropertyDataType(enum.StrEnum):
    STRING = "string"
    INTEGER = "integer"
    DOUBLE = "double"
    DECIMAL = "decimal"
    BOOLEAN = "boolean"
    DATE = "date"
    TIMESTAMP = "timestamp"
    JSON = "json"
    GEOPOINT = "geopoint"  # stored in object_instance.geometry (PostGIS)
    GEOSHAPE = "geoshape"  # stored in object_instance.geometry (PostGIS)
    TIMESERIES = "timeseries"  # values live in TimescaleDB; `binding` says where
    MEDIA_REF = "media_ref"  # object-store URI: RGB / thermal / LiDAR


GEO_TYPES = frozenset({PropertyDataType.GEOPOINT, PropertyDataType.GEOSHAPE})


class Cardinality(enum.StrEnum):
    ONE_TO_ONE = "one_to_one"
    ONE_TO_MANY = "one_to_many"
    MANY_TO_ONE = "many_to_one"
    MANY_TO_MANY = "many_to_many"


class AgentAccess(enum.StrEnum):
    NONE = "none"  # AI agents cannot use this action
    PROPOSE = "propose"  # agents may draft an execution; a human must approve it


class ActorType(enum.StrEnum):
    USER = "user"
    SERVICE = "service"
    AGENT = "agent"


class ExecutionStatus(enum.StrEnum):
    PENDING_APPROVAL = "pending_approval"
    REJECTED = "rejected"
    SUCCEEDED = "succeeded"  # ontology edits committed; write-backs are in the outbox
    FAILED = "failed"


class OutboxStatus(enum.StrEnum):
    PENDING = "pending"
    DELIVERED = "delivered"
    DEAD = "dead"  # retries exhausted; needs an operator


class AuditOutcome(enum.StrEnum):
    SUCCESS = "success"
    DENIED = "denied"
    ERROR = "error"


# --------------------------------------------------------------------------- #
# Base, helpers, mixins
# --------------------------------------------------------------------------- #

NAMING_CONVENTION = {
    "pk": "pk_%(table_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
}

PASCAL = "^[A-Z][A-Za-z0-9]{0,62}$"
CAMEL = "^[a-z][A-Za-z0-9]{0,62}$"


class Base(DeclarativeBase):
    metadata = MetaData(schema="ontology", naming_convention=NAMING_CONVENTION)


def _pk() -> Mapped[uuid.UUID]:
    return mapped_column(UUID(as_uuid=True), primary_key=True, server_default=text("uuidv7()"))


def _fk(target: str, ondelete: str = "RESTRICT") -> Mapped[uuid.UUID]:
    return mapped_column(UUID(as_uuid=True), ForeignKey(target, ondelete=ondelete))


def _enum(py_enum: type[enum.Enum], name: str) -> Enum:
    return Enum(
        py_enum,
        name=name,
        native_enum=False,
        create_constraint=True,
        length=32,
        values_callable=lambda e: [member.value for member in e],
    )


def _jsonb(default: str) -> Mapped[Any]:
    return mapped_column(JSONB, server_default=text(f"'{default}'::jsonb"))


def _markings() -> Mapped[list[str]]:
    """Security markings (e.g. 'restricted', 'region:IN-TG') for attribute-based policy."""
    return mapped_column(ARRAY(Text), server_default=text("'{}'::text[]"))


class TenantMixin:
    tenant_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))


class StampMixin:
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now()
    )
    created_by: Mapped[str] = mapped_column(Text)  # OIDC `sub` of the actor


# --------------------------------------------------------------------------- #
# Metamodel
# --------------------------------------------------------------------------- #


class ObjectType(Base, TenantMixin, StampMixin):
    """A class of real-world thing: CommercialDrone, Substation, WorkOrder."""

    __tablename__ = "object_type"

    id: Mapped[uuid.UUID] = _pk()
    api_name: Mapped[str] = mapped_column(Text)
    display_name: Mapped[str] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    status: Mapped[LifecycleStatus] = mapped_column(_enum(LifecycleStatus, "status"), server_default="draft")
    # Bumped on every definition change. Doubles as the optimistic-lock column.
    version: Mapped[int] = mapped_column(Integer, server_default=text("1"))
    # Lakehouse dataset this type is materialised from, e.g. `assets.commercial_drone`.
    backing_dataset: Mapped[str | None] = mapped_column(Text)
    markings: Mapped[list[str]] = _markings()
    ui: Mapped[dict[str, Any]] = _jsonb("{}")  # icon, colour, map style for Workshop

    properties: Mapped[list[PropertyType]] = relationship(
        back_populates="object_type", cascade="all, delete-orphan", order_by="PropertyType.api_name"
    )

    __mapper_args__ = {"version_id_col": version}
    __table_args__ = (
        UniqueConstraint("tenant_id", "api_name"),
        CheckConstraint(f"api_name ~ '{PASCAL}'", name="api_name_pascal"),
    )


class PropertyType(Base, TenantMixin, StampMixin):
    """A typed attribute of an ObjectType, optionally bound to a dataset column or a series."""

    __tablename__ = "property_type"

    id: Mapped[uuid.UUID] = _pk()
    object_type_id: Mapped[uuid.UUID] = _fk("object_type.id", ondelete="CASCADE")
    api_name: Mapped[str] = mapped_column(Text)
    display_name: Mapped[str] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    data_type: Mapped[PropertyDataType] = mapped_column(_enum(PropertyDataType, "data_type"))
    is_array: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    is_primary_key: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    is_title: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    is_required: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    unit: Mapped[str | None] = mapped_column(Text)  # UCUM code: V, Cel, m/s
    source_column: Mapped[str | None] = mapped_column(Text)  # column in backing_dataset
    # timeseries: {"metric": "battery_voltage"}   media_ref: {"kinds": ["thermal"]}
    binding: Mapped[dict[str, Any] | None] = mapped_column(JSONB)
    constraints: Mapped[dict[str, Any]] = _jsonb("{}")  # enum / minimum / maximum / pattern
    markings: Mapped[list[str]] = _markings()
    status: Mapped[LifecycleStatus] = mapped_column(_enum(LifecycleStatus, "status"), server_default="active")

    object_type: Mapped[ObjectType] = relationship(back_populates="properties")

    __table_args__ = (
        UniqueConstraint("object_type_id", "api_name"),
        CheckConstraint(f"api_name ~ '{CAMEL}'", name="api_name_camel"),
        CheckConstraint("data_type <> 'timeseries' OR binding IS NOT NULL", name="timeseries_bound"),
        CheckConstraint(
            "NOT is_primary_key OR (data_type IN ('string', 'integer') AND NOT is_array AND is_required)",
            name="primary_key_scalar",
        ),
        # At most one primary key and one title property per object type.
        Index(
            "uq_property_type_one_pk", "object_type_id", unique=True, postgresql_where=text("is_primary_key")
        ),
        Index("uq_property_type_one_title", "object_type_id", unique=True, postgresql_where=text("is_title")),
    )


class LinkType(Base, TenantMixin, StampMixin):
    """A typed, directional relationship: CommercialDrone -inspects-> Substation."""

    __tablename__ = "link_type"

    id: Mapped[uuid.UUID] = _pk()
    api_name: Mapped[str] = mapped_column(Text)  # inspects
    display_name: Mapped[str] = mapped_column(Text)
    reverse_api_name: Mapped[str] = mapped_column(Text)  # inspectedBy
    reverse_display_name: Mapped[str] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    source_object_type_id: Mapped[uuid.UUID] = _fk("object_type.id")
    target_object_type_id: Mapped[uuid.UUID] = _fk("object_type.id")
    cardinality: Mapped[Cardinality] = mapped_column(_enum(Cardinality, "cardinality"))
    status: Mapped[LifecycleStatus] = mapped_column(_enum(LifecycleStatus, "status"), server_default="draft")

    source_object_type: Mapped[ObjectType] = relationship(foreign_keys=[source_object_type_id], lazy="joined")
    target_object_type: Mapped[ObjectType] = relationship(foreign_keys=[target_object_type_id], lazy="joined")

    __table_args__ = (
        UniqueConstraint("source_object_type_id", "api_name"),
        UniqueConstraint("target_object_type_id", "reverse_api_name"),
        CheckConstraint(f"api_name ~ '{CAMEL}' AND reverse_api_name ~ '{CAMEL}'", name="api_names_camel"),
    )


class ActionType(Base, TenantMixin, StampMixin):
    """A governed, transactional mutation: groundDrone, createWorkOrder."""

    __tablename__ = "action_type"

    id: Mapped[uuid.UUID] = _pk()
    api_name: Mapped[str] = mapped_column(Text)
    display_name: Mapped[str] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    target_object_type_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("object_type.id", ondelete="RESTRICT")
    )
    status: Mapped[LifecycleStatus] = mapped_column(_enum(LifecycleStatus, "status"), server_default="draft")
    version: Mapped[int] = mapped_column(Integer, server_default=text("1"))
    parameters: Mapped[dict[str, Any]] = _jsonb("{}")  # JSON Schema for the inputs
    edits: Mapped[list[dict[str, Any]]] = _jsonb("[]")  # ordered OntologyEdit list
    writeback: Mapped[list[dict[str, Any]]] = _jsonb("[]")  # WritebackSpec list -> outbox
    # OPA package answering both "may this actor do it" and "do the business rules hold".
    policy_path: Mapped[str] = mapped_column(Text, server_default="s2/actions/standard")
    requires_approval: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    agent_access: Mapped[AgentAccess] = mapped_column(
        _enum(AgentAccess, "agent_access"), server_default="none"
    )

    target_object_type: Mapped[ObjectType | None] = relationship(lazy="joined")

    __mapper_args__ = {"version_id_col": version}
    __table_args__ = (
        UniqueConstraint("tenant_id", "api_name"),
        CheckConstraint(f"api_name ~ '{CAMEL}'", name="api_name_camel"),
    )


# --------------------------------------------------------------------------- #
# Runtime
# --------------------------------------------------------------------------- #


class TriageRule(Base, TenantMixin, StampMixin):
    """Conditions over one object type; the objects that meet them all form a work queue."""

    __tablename__ = "triage_rule"

    id: Mapped[uuid.UUID] = _pk()
    api_name: Mapped[str] = mapped_column(Text)
    display_name: Mapped[str] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    object_type_id: Mapped[uuid.UUID] = _fk("object_type.id", ondelete="RESTRICT")
    severity: Mapped[str] = mapped_column(Text, server_default="medium")
    # [{"property": "actuatorHealth", "op": "lt", "value": 0.8, "max_age_s": 900}, ...]
    conditions: Mapped[list[dict[str, Any]]] = _jsonb("[]")
    actions: Mapped[list[str]] = mapped_column(ARRAY(Text), server_default=text("'{}'::text[]"))
    status: Mapped[LifecycleStatus] = mapped_column(_enum(LifecycleStatus, "status"), server_default="active")
    version: Mapped[int] = mapped_column(Integer, server_default=text("1"))

    object_type: Mapped[ObjectType] = relationship(lazy="joined")

    __mapper_args__ = {"version_id_col": version}
    __table_args__ = (
        UniqueConstraint("tenant_id", "api_name"),
        CheckConstraint(f"api_name ~ '{CAMEL}'", name="api_name_camel"),
    )


class ObjectInstance(Base, TenantMixin, StampMixin):
    """One real thing. Scalar properties in JSONB, shape in PostGIS, series in TimescaleDB."""

    __tablename__ = "object_instance"

    id: Mapped[uuid.UUID] = _pk()
    object_type_id: Mapped[uuid.UUID] = _fk("object_type.id")
    # Value of the type's primary-key property. With the type's api_name this is the
    # natural key telemetry is written under, so readings can arrive before the object does.
    primary_key: Mapped[str] = mapped_column(Text)
    properties: Mapped[dict[str, Any]] = _jsonb("{}")
    # Written and read as GeoJSON through PostGIS functions (domain/objects.py), so it is
    # never loaded as part of the entity.
    geometry: Mapped[Any | None] = mapped_column(
        Geometry("GEOMETRY", srid=4326, spatial_index=False), deferred=True
    )
    version: Mapped[int] = mapped_column(Integer, server_default=text("1"))

    __mapper_args__ = {"version_id_col": version}
    __table_args__ = (
        UniqueConstraint("object_type_id", "primary_key"),
        Index("ix_object_instance_tenant_type", "tenant_id", "object_type_id"),
        Index(
            "ix_object_instance_properties",
            "properties",
            postgresql_using="gin",
            postgresql_ops={"properties": "jsonb_path_ops"},
        ),
        Index("ix_object_instance_geometry", "geometry", postgresql_using="gist"),
    )


class LinkInstance(Base, TenantMixin, StampMixin):
    __tablename__ = "link_instance"

    id: Mapped[uuid.UUID] = _pk()
    link_type_id: Mapped[uuid.UUID] = _fk("link_type.id")
    source_object_id: Mapped[uuid.UUID] = _fk("object_instance.id", ondelete="CASCADE")
    target_object_id: Mapped[uuid.UUID] = _fk("object_instance.id", ondelete="CASCADE")
    properties: Mapped[dict[str, Any]] = _jsonb("{}")

    __table_args__ = (
        UniqueConstraint("link_type_id", "source_object_id", "target_object_id"),
        Index("ix_link_instance_reverse", "target_object_id", "link_type_id"),  # reverse traversal
    )


class ActionExecution(Base, TenantMixin):
    """One invocation of an ActionType, from request through approval to outcome."""

    __tablename__ = "action_execution"

    id: Mapped[uuid.UUID] = _pk()
    action_type_id: Mapped[uuid.UUID] = _fk("action_type.id")
    action_type_version: Mapped[int] = mapped_column(Integer)
    status: Mapped[ExecutionStatus] = mapped_column(_enum(ExecutionStatus, "status"))
    parameters: Mapped[dict[str, Any]] = _jsonb("{}")
    actor_type: Mapped[ActorType] = mapped_column(_enum(ActorType, "actor_type"))
    actor_id: Mapped[str] = mapped_column(Text)
    on_behalf_of: Mapped[str | None] = mapped_column(Text)  # the human an agent acts for
    approved_by: Mapped[str | None] = mapped_column(Text)
    policy_decision_id: Mapped[str | None] = mapped_column(Text)
    idempotency_key: Mapped[str] = mapped_column(Text)
    error: Mapped[dict[str, Any] | None] = mapped_column(JSONB)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    completed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    action_type: Mapped[ActionType] = relationship(lazy="joined")
    writebacks: Mapped[list[WritebackOutbox]] = relationship(
        back_populates="execution", cascade="all, delete-orphan", order_by="WritebackOutbox.created_at"
    )

    __table_args__ = (
        UniqueConstraint("tenant_id", "idempotency_key"),
        Index("ix_action_execution_type_created", "action_type_id", "created_at"),
        CheckConstraint("actor_type <> 'agent' OR on_behalf_of IS NOT NULL", name="agent_has_principal"),
    )


class WritebackOutbox(Base, TenantMixin):
    """Transactional outbox. Written in the same transaction as the ontology edits,
    delivered at-least-once to ERP / CMMS / fleet by services/action-executor."""

    __tablename__ = "writeback_outbox"

    id: Mapped[uuid.UUID] = _pk()  # also the idempotency key sent to the target system
    action_execution_id: Mapped[uuid.UUID] = _fk("action_execution.id", ondelete="CASCADE")
    connector: Mapped[str] = mapped_column(Text)  # cmms, sap-pm, samanvaya-fleet
    operation: Mapped[str] = mapped_column(Text)
    payload: Mapped[dict[str, Any]] = _jsonb("{}")
    status: Mapped[OutboxStatus] = mapped_column(_enum(OutboxStatus, "status"), server_default="pending")
    attempts: Mapped[int] = mapped_column(Integer, server_default=text("0"))
    next_attempt_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    delivered_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    last_error: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())

    execution: Mapped[ActionExecution] = relationship(back_populates="writebacks")

    __table_args__ = (
        # The relay polls this with SELECT ... FOR UPDATE SKIP LOCKED.
        Index("ix_writeback_outbox_due", "next_attempt_at", postgresql_where=text("status = 'pending'")),
    )


# --------------------------------------------------------------------------- #
# Governance
# --------------------------------------------------------------------------- #


class AuditLog(Base, TenantMixin):
    """Append-only, hash-chained per tenant.

    seq, occurred_at, prev_hash and entry_hash are set by a BEFORE INSERT trigger and
    cannot be supplied by a client; UPDATE, DELETE and TRUNCATE are rejected by triggers.
    `ontology.audit_verify(tenant)` re-walks the chain.
    """

    __tablename__ = "audit_log"

    id: Mapped[uuid.UUID] = _pk()
    seq: Mapped[int] = mapped_column(BigInteger, server_default=FetchedValue())
    occurred_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=FetchedValue())
    prev_hash: Mapped[bytes] = mapped_column(LargeBinary, server_default=FetchedValue())
    entry_hash: Mapped[bytes] = mapped_column(LargeBinary, server_default=FetchedValue())
    actor_type: Mapped[ActorType] = mapped_column(_enum(ActorType, "actor_type"))
    actor_id: Mapped[str] = mapped_column(Text)
    on_behalf_of: Mapped[str | None] = mapped_column(Text)
    # Dotted verb: ontology.pack.applied, action.executed, authz.denied
    event_type: Mapped[str] = mapped_column(Text)
    resource_type: Mapped[str | None] = mapped_column(Text)
    resource_id: Mapped[str | None] = mapped_column(Text)
    outcome: Mapped[AuditOutcome] = mapped_column(_enum(AuditOutcome, "outcome"))
    policy_decision_id: Mapped[str | None] = mapped_column(Text)  # OPA decision log id
    trace_id: Mapped[str | None] = mapped_column(Text)  # W3C trace id of the request
    details: Mapped[dict[str, Any]] = _jsonb("{}")  # inputs, before/after diff

    __table_args__ = (
        UniqueConstraint("tenant_id", "seq"),
        Index("ix_audit_log_resource", "tenant_id", "resource_type", "resource_id"),
        Index("ix_audit_log_event", "tenant_id", "event_type", "occurred_at"),
    )
